package genesismesh

import (
	"crypto/ed25519"
	"encoding/base64"
	"encoding/json"
	"os"
	"reflect"
	"testing"
	"time"
)

// Shared conformance suite "grants" (v1.6.0), generated by the Python
// reference (genesismesh/conformance/generate_vectors.py grants) and copied
// unchanged. This SDK runs the vectors of what it verifies: the signed forms
// of the grant records and the revocation feed, and their signatures as
// received. Envelopes, issuance, uses and evidence exports are checked by the
// core and the TypeScript and Rust SDKs.

type grantsVector struct {
	ID          string          `json:"id"`
	Kind        string          `json:"kind"`
	Description string          `json:"description"`
	Model       string          `json:"model"`
	Record      json.RawMessage `json:"record"`
	PublicKey   string          `json:"public_key"`
	Expected    json.RawMessage `json:"expected"`
}

var grantsKindsNotRun = map[string]bool{
	"envelope_parameter": true, "envelope": true, "issuance": true, "use": true, "verify_export": true,
}

func loadGrantsVectors(t *testing.T) []grantsVector {
	t.Helper()
	raw, err := os.ReadFile("testdata/conformance/grants.json")
	if err != nil {
		t.Fatal(err)
	}
	var suite struct {
		Suite   string         `json:"suite"`
		Vectors []grantsVector `json:"vectors"`
	}
	if err := json.Unmarshal(raw, &suite); err != nil {
		t.Fatal(err)
	}
	if suite.Suite != "grants" || len(suite.Vectors) == 0 {
		t.Fatalf("unexpected suite %q with %d vectors", suite.Suite, len(suite.Vectors))
	}
	return suite.Vectors
}

func grantsVectorByID(t *testing.T, id string) grantsVector {
	t.Helper()
	for _, v := range loadGrantsVectors(t) {
		if v.ID == id {
			return v
		}
	}
	t.Fatalf("no vector %s", id)
	return grantsVector{}
}

func TestConformanceGrantsVectors(t *testing.T) {
	kinds := map[string]int{}
	for _, v := range loadGrantsVectors(t) {
		v := v
		kinds[v.Kind]++
		if grantsKindsNotRun[v.Kind] {
			continue
		}
		t.Run(v.ID, func(t *testing.T) {
			record, err := decodeObject(v.Record, "record")
			if err != nil {
				t.Fatal(err)
			}
			var got interface{}
			switch v.Kind {
			case "canonical_form":
				c, err := receivedCanonical(v.Model, record)
				if err != nil {
					t.Fatal(err)
				}
				got = map[string]interface{}{"canonical": c, "digest": sha256Hex(c)}
			case "verify_record":
				got = map[string]interface{}{"valid": signedAsReceived(v.Model, record, []string{v.PublicKey})}
			default:
				t.Fatalf("vector kind %q is neither run nor listed as not run", v.Kind)
			}
			gotRaw, _ := json.Marshal(got)
			var g, w interface{}
			_ = json.Unmarshal(gotRaw, &g)
			_ = json.Unmarshal(v.Expected, &w)
			if !reflect.DeepEqual(g, w) {
				t.Fatalf("%s\n got:  %s\n want: %s", v.Description, gotRaw, v.Expected)
			}
		})
	}
	for _, kind := range []string{"canonical_form", "verify_record"} {
		if kinds[kind] == 0 {
			t.Errorf("no %s vectors", kind)
		}
	}
}

func TestARevocationFeedWithGrantsHasNoUnknownField(t *testing.T) {
	// v1.6.0: with grants on, the NA's feed lists revoked_grant_ids; while
	// they are off it keeps its 1.5 form. Both are known, signed forms.
	for _, id := range []string{"signature-feed-with-grants", "signature-feed-without-grants"} {
		v := grantsVectorByID(t, id)
		unknown, err := UnknownFields("SovereignRevocationFeed", v.Record)
		if err != nil || len(unknown) != 0 {
			t.Errorf("%s: unknown fields %v %v", id, unknown, err)
		}
		record, _ := decodeObject(v.Record, "feed")
		if bad := nonCanonicalFields("SovereignRevocationFeed", record); len(bad) != 0 {
			t.Errorf("%s: not in canonical form at %v", id, bad)
		}
	}
}

// grantSignedBy is the suite's grant with changes, signed again by key.
func grantSignedBy(t *testing.T, key ed25519.PrivateKey, changes map[string]interface{}) []byte {
	t.Helper()
	grant, err := decodeObject(grantsVectorByID(t, "signature-CapabilityGrant-signer").Record, "grant")
	if err != nil {
		t.Fatal(err)
	}
	for k, v := range changes {
		if v == nil {
			delete(grant, k)
		} else {
			grant[k] = v
		}
	}
	c, err := receivedCanonical("CapabilityGrant", grant)
	if err != nil {
		t.Fatal(err)
	}
	grant["signature"] = map[string]interface{}{
		"key_id": "na-key", "sig": base64.StdEncoding.EncodeToString(ed25519.Sign(key, []byte(c))),
	}
	return mustJSON(t, grant)
}

func TestVerifyCapabilityGrant(t *testing.T) {
	signed := grantsVectorByID(t, "signature-CapabilityGrant-signer")
	other := grantsVectorByID(t, "signature-CapabilityGrant-other-key").PublicKey
	record, _ := decodeObject(signed.Record, "grant")
	issued, err := ParseTimestamp(str(record, "issued_at"))
	if err != nil {
		t.Fatal(err)
	}
	verify := func(raw []byte, history *NAKeyHistory) string {
		t.Helper()
		got, err := VerifyCapabilityGrant(raw, history)
		if err != nil {
			t.Fatal(err)
		}
		if got.Valid != (got.Reason == "accepted") || got.GrantID == "" {
			t.Errorf("inconsistent result %+v", got)
		}
		return got.Reason
	}
	if got := verify(signed.Record, NAKeysValidAlways([]string{signed.PublicKey})); got != "accepted" {
		t.Errorf("the NA's grant: %s", got)
	}
	if got := verify(signed.Record, NAKeysValidAlways([]string{other})); got != "invalid_signature" {
		t.Errorf("another key: %s", got)
	}
	unsigned := withValue(t, signed.Record, "signature", nil)
	if got := verify(mustJSON(t, unsigned), NAKeysValidAlways([]string{signed.PublicKey})); got != "missing_signature" {
		t.Errorf("no signature: %s", got)
	}

	// The key valid at issued_at: the signer took over from another key an
	// hour before the grant was issued, or takes over an hour after it.
	before, after := issued.Add(-time.Hour), issued.Add(time.Hour)
	succeeded := func(at time.Time) *NAKeyHistory {
		return &NAKeyHistory{Keys: []NAKey{
			{KeySequence: 1, PublicKey: other, SucceededAt: &at},
			{KeySequence: 2, PublicKey: signed.PublicKey, ValidFrom: &at},
		}}
	}
	if got := verify(signed.Record, succeeded(before)); got != "accepted" {
		t.Errorf("signed by the key valid at issued_at: %s", got)
	}
	if got := verify(signed.Record, succeeded(after)); got != "na_key_not_valid_at_time" {
		t.Errorf("signed by a key not yet valid at issued_at: %s", got)
	}

	// Strict: a signed field this SDK does not know, or a form the reference
	// does not write, is refused by name when the signature verifies.
	key := seededKey(0x61)
	keys := NAKeysValidAlways([]string{pubOf(key)})
	if got := verify(grantSignedBy(t, key, nil), keys); got != "accepted" {
		t.Errorf("signed again: %s", got)
	}
	if got := verify(grantSignedBy(t, key, map[string]interface{}{"delegable": true}), keys); got != "unknown_field" {
		t.Errorf("an unknown field: %s", got)
	}
	if got := verify(grantSignedBy(t, key, map[string]interface{}{"issued_at": "2026-01-01T00:00:00+00:00"}), keys); got != "non_canonical_form" {
		t.Errorf("a timestamp the reference does not write: %s", got)
	}
	if got := verify(grantSignedBy(t, key, map[string]interface{}{"max_uses_per_time_token": nil}), keys); got != "non_canonical_form" {
		t.Errorf("a field left out: %s", got)
	}

	if _, err := VerifyCapabilityGrant(signed.Record, nil); err == nil {
		t.Error("no key history: no error")
	}
}
